        static byte[] RuntimeReport()
        {
            var services = Property(Interface(_host, "IHost"), _host, "Services") as IServiceProvider;
            using (var buffer = new MemoryStream())
            {
                using (var w = new Utf8JsonWriter(buffer))
                {
                    w.WriteStartObject();
                    w.WriteNumber("pid", Environment.ProcessId);
                    w.WriteString("app", Assembly.GetEntryAssembly()?.GetName().Name ?? "app");
                    var environment = Find(services, "Microsoft.Extensions.Hosting.IHostEnvironment") is Type envType ? services.GetService(envType) : null;
                    w.WriteString("environment", Property(environment, "EnvironmentName") as string);

                    w.WriteStartArray("addresses");
                    foreach (var address in Addresses(services)) w.WriteStringValue(address);
                    w.WriteEndArray();

                    w.WriteStartArray("services");
                    if (_services is IEnumerable descriptors)
                        foreach (var d in descriptors) WriteService(w, d);
                    w.WriteEndArray();

                    w.WriteStartArray("endpoints");
                    foreach (var e in Endpoints(services)) WriteEndpoint(w, e);
                    w.WriteEndArray();
                    w.WriteEndObject();
                }
                return buffer.ToArray();
            }
        }

        static void WriteService(Utf8JsonWriter w, object d)
        {
