            {
                var keyed = Property(d, "IsKeyedService") is bool k && k;
                var service = Property(d, "ServiceType") as Type;
                var impl = Property(d, keyed ? "KeyedImplementationType" : "ImplementationType") as Type;
                var instance = Property(d, keyed ? "KeyedImplementationInstance" : "ImplementationInstance");
                var factory = Property(d, keyed ? "KeyedImplementationFactory" : "ImplementationFactory");
                if (impl == null && instance != null) impl = instance.GetType();
                if (service == null || (Framework(service) && (impl == null || Framework(impl)))) return;

                w.WriteStartObject();
                w.WriteString("service", Name(service));
                w.WriteString("serviceAssembly", service.Assembly.GetName().Name);
                w.WriteString("serviceName", Display(service));
                if (impl != null)
                {
                    w.WriteString("impl", Name(impl));
                    w.WriteString("implAssembly", impl.Assembly.GetName().Name);
                    w.WriteString("implName", Display(impl));
                }
                w.WriteString("lifetime", Property(d, "Lifetime")?.ToString() ?? "");
                w.WriteBoolean("factory", factory != null);
                w.WriteBoolean("instance", instance != null);
                w.WriteEndObject();
            }
            catch (Exception)
            {
                // One odd registration should not cost the rest.
            }
