        static bool Framework(Type t)
        {
            var name = t.Assembly.GetName().Name ?? "";
            return name.StartsWith("Microsoft.", StringComparison.Ordinal) || name.StartsWith("System.", StringComparison.Ordinal) || name == "System" || name == "netstandard";
        }

        /// <summary>"Ns.Outer+Inner", and the definition for generic types ("Ns.Repo`1").</summary>
        static string Name(Type t)
