            return definition.FullName ?? definition.Name;
        }

        /// <summary>"IRequestHandler&lt;PlaceOrder, OrderDto&gt;", as people write it.</summary>
        static string Display(Type t)
        {
            if (!t.IsGenericType) return t.Name;
            var name = t.Name;
            var tick = name.IndexOf('`');
            if (tick > 0) name = name.Substring(0, tick);
            var args = new List<string>();
            foreach (var a in t.GetGenericArguments()) args.Add(Display(a));
            return name + "<" + string.Join(", ", args) + ">";
        }

        static IEnumerable<string> Addresses(IServiceProvider services)
        {
            var result = new List<string>();
            var serverType = Find(services, "Microsoft.AspNetCore.Hosting.Server.IServer");
            var server = serverType == null ? null : services.GetService(serverType);
            if (Property(server, "Features") is IEnumerable features)
            {
                foreach (var pair in features)
                {
                    if (Property(Property(pair, "Value"), "Addresses") is IEnumerable addresses)
                        foreach (var a in addresses) if (a is string s) result.Add(s.Replace("://[::]", "://localhost").Replace("://0.0.0.0", "://localhost").Replace("://+", "://localhost").Replace("://*", "://localhost"));
                }
            }
            return result;
        }

        static IEnumerable<object> Endpoints(IServiceProvider services)
        {
            var sourceType = Find(services, "Microsoft.AspNetCore.Routing.EndpointDataSource");
            var source = sourceType == null ? null : services.GetService(sourceType);
            var result = new List<object>();
            if (Property(source, "Endpoints") is IEnumerable endpoints)
                foreach (var e in endpoints) result.Add(e);
            return result;
        }

        static void WriteEndpoint(Utf8JsonWriter w, object endpoint)
        {
            try
            {
                var route = Property(Property(endpoint, "RoutePattern"), "RawText") as string;
                if (route == null) return;

                var methods = new List<string>();
                MethodInfo handler = null;
                Type handlerType = null;
                if (Property(endpoint, "Metadata") is IEnumerable metadata)
                {
                    foreach (var item in metadata)
                    {
                        if (item == null) continue;
                        if (Property(item, "HttpMethods") is IEnumerable verbs && item.GetType().Name.Contains("HttpMethod"))
                            foreach (var v in verbs) if (v is string s && !methods.Contains(s)) methods.Add(s);
                        if (item is MethodInfo m && handler == null) handler = m;
                        if (Property(item, "MethodInfo") is MethodInfo action && Property(item, "ControllerTypeInfo") is Type controller)
                        {
                            handler = action;
                            handlerType = controller;
                        }
                    }
                }
                handlerType = handlerType ?? handler?.DeclaringType;
                // Lambdas live in compiler-made classes; their method names mean nothing to anyone.
                if (handlerType != null && handlerType.Name.IndexOf('<') >= 0) { handler = null; handlerType = null; }

                w.WriteStartObject();
                w.WriteString("route", route);
                w.WriteStartArray("methods");
                foreach (var m in methods) w.WriteStringValue(m);
                w.WriteEndArray();
                w.WriteString("name", Property(endpoint, "DisplayName") as string);
                if (handlerType != null && handler != null)
                {
                    w.WriteString("handlerType", Name(handlerType));
                    w.WriteString("handlerAssembly", handlerType.Assembly.GetName().Name);
                    w.WriteString("handlerMethod", handler.Name);
                }
                w.WriteEndObject();
            }
            catch (Exception)
            {
                // skip this endpoint
            }
        }

        // ------------------------------------------------------------ requests

        sealed class Request
        {
            public DateTime Start;
            public Stopwatch Clock;
            public string Error;
            public readonly List<string[]> Sql = new List<string[]>();         // text, ms, error
            public readonly List<string[]> Http = new List<string[]>();        // method, url, status, ms
        }

        static string CurrentTrace()
        {
            var a = Activity.Current;
            return a == null ? null : a.TraceId.ToHexString();
        }

        static void OnRequest(string name, object payload)
        {
            if (name == "Microsoft.AspNetCore.Hosting.HttpRequestIn.Start")
            {
                var trace = CurrentTrace();
                if (trace != null) Requests[trace] = new Request { Start = DateTime.UtcNow, Clock = Stopwatch.StartNew() };
            }
            else if (name == "Microsoft.AspNetCore.Hosting.HttpRequestIn.Stop")
            {
                var trace = CurrentTrace();
                if (trace == null || !Requests.TryRemove(trace, out var request)) return;
                var http = payload;
                var path = Property(Property(http, "Request"), "Path")?.ToString() ?? "/";
                if (path.StartsWith("/sightline", StringComparison.OrdinalIgnoreCase)) return;

                var route = Route(http);
                var status = Property(Property(http, "Response"), "StatusCode") is int code ? code : 0;
                if (route == null && status < 400 && Path.HasExtension(path)) return;     // static files

                Finished.Enqueue(TraceReport(trace, request,
                    Property(Property(http, "Request"), "Method") as string ?? "GET", path,
                    Property(Property(http, "Request"), "QueryString")?.ToString(), route, status));
                Wake.Set();
            }
            else if (name.EndsWith("UnhandledException", StringComparison.Ordinal))
            {
                var trace = CurrentTrace();
                if (trace != null && Requests.TryGetValue(trace, out var request) && Property(payload, "exception") is Exception ex)
                    request.Error = ex.GetType().Name + ": " + ex.Message;
            }
        }

        /// <summary>The route pattern the request matched, from the endpoint feature of the HttpContext.</summary>
        static string Route(object http)
        {
            if (!(Property(http, "Features") is IEnumerable features)) return null;
            foreach (var pair in features)
            {
                if (!(Property(pair, "Key") is Type key) || key.Name != "IEndpointFeature") continue;
                return Property(Property(Property(Property(pair, "Value"), "Endpoint"), "RoutePattern"), "RawText") as string;
            }
            return null;
        }

        static void OnDatabase(string name, object payload)
        {
            var trace = CurrentTrace();
            if (trace == null || !Requests.TryGetValue(trace, out var request)) return;
            var text = Property(Property(payload, "Command"), "CommandText") as string ?? "";
            var ms = Property(payload, "Duration") is TimeSpan d ? d.TotalMilliseconds : 0;
            var error = name.EndsWith("CommandError", StringComparison.Ordinal) && Property(payload, "Exception") is Exception ex ? ex.Message : null;
            lock (request.Sql)
                if (request.Sql.Count < 50) request.Sql.Add(new[] { text, ms.ToString("0.0", global::System.Globalization.CultureInfo.InvariantCulture), error });
        }

        static void OnHttp(string name, object payload)
        {
            if (name != "System.Net.Http.HttpRequestOut.Stop") return;
            var trace = CurrentTrace();
            if (trace == null || !Requests.TryGetValue(trace, out var request)) return;
            var message = Property(payload, "Request");
            var status = Property(Property(payload, "Response"), "StatusCode");
            var ms = Activity.Current?.Duration.TotalMilliseconds ?? 0;
            lock (request.Http)
                if (request.Http.Count < 50)
                    request.Http.Add(new[]
                    {
                        Property(message, "Method")?.ToString() ?? "GET", Property(message, "RequestUri")?.ToString() ?? "",
                        status == null ? null : Convert.ToInt32(status, global::System.Globalization.CultureInfo.InvariantCulture).ToString(global::System.Globalization.CultureInfo.InvariantCulture),
                        ms.ToString("0.0", global::System.Globalization.CultureInfo.InvariantCulture),
                    });
        }

        static byte[] TraceReport(string trace, Request r, string method, string path, string query, string route, int status)
        {
            using (var buffer = new MemoryStream())
            {
                using (var w = new Utf8JsonWriter(buffer))
                {
                    w.WriteStartObject();
                    w.WriteString("id", trace);
                    w.WriteString("method", method);
                    w.WriteString("path", path);
                    if (!string.IsNullOrEmpty(query)) w.WriteString("query", query);
                    if (route != null) w.WriteString("route", route);
                    w.WriteNumber("status", status);
                    w.WriteNumber("ms", Math.Round(r.Clock.Elapsed.TotalMilliseconds, 1));
                    w.WriteString("start", r.Start);
                    w.WriteStartArray("sql");
                    lock (r.Sql)
                        foreach (var s in r.Sql)
                        {
                            w.WriteStartObject();
                            w.WriteString("text", s[0]);
                            w.WriteNumber("ms", double.Parse(s[1], global::System.Globalization.CultureInfo.InvariantCulture));
                            if (s[2] != null) w.WriteString("error", s[2]);
                            w.WriteEndObject();
                        }
                    w.WriteEndArray();
                    w.WriteStartArray("http");
                    lock (r.Http)
                        foreach (var h in r.Http)
                        {
                            w.WriteStartObject();
                            w.WriteString("method", h[0]);
                            w.WriteString("url", h[1]);
                            if (h[2] != null) w.WriteNumber("status", int.Parse(h[2], global::System.Globalization.CultureInfo.InvariantCulture));
                            w.WriteNumber("ms", double.Parse(h[3], global::System.Globalization.CultureInfo.InvariantCulture));
                            w.WriteEndObject();
                        }
                    w.WriteEndArray();
                    if (r.Error != null) w.WriteString("error", r.Error);
                    w.WriteEndObject();
                }
                return buffer.ToArray();
            }
        }

        // ------------------------------------------------------------ sending

        /// <summary>
        /// Runs on its own thread, started outside any request, so its HTTP calls are never mistaken
        /// for calls the app makes while handling a request.
        /// </summary>
        static void Send()
        {
            var http = new HttpClient { Timeout = TimeSpan.FromSeconds(5) };
            while (true)
            {
                Wake.WaitOne(500);
                string url, token;
                lock (Gate)
                {
                    url = _url;
                    token = _token;
                }
                if (url == null) continue;

                try
                {
                    if (_started && !_reported && _host != null)
                    {
                        Post(http, url + "/api/runtime", token, RuntimeReport());
                        _reported = true;
                    }

                    var batch = new List<byte[]>();
                    while (batch.Count < 50 && Finished.TryDequeue(out var item)) batch.Add(item);
                    while (Finished.Count > 500 && Finished.TryDequeue(out _)) { }      // the map is gone; do not pile up
                    if (batch.Count > 0) Post(http, url + "/api/trace", token, Batch(batch));
                }
                catch (Exception)
                {
                    // The map may be restarting; the next round tries again.
                }
            }
        }

        static byte[] Batch(List<byte[]> traces)
        {
            using (var buffer = new MemoryStream())
            {
                var head = Encoding.UTF8.GetBytes("{\"pid\":" + Environment.ProcessId + ",\"app\":" +
                    JsonSerializer.Serialize(Assembly.GetEntryAssembly()?.GetName().Name ?? "app") + ",\"traces\":[");
                buffer.Write(head, 0, head.Length);
                for (var i = 0; i < traces.Count; i++)
                {
                    if (i > 0) buffer.WriteByte((byte)',');
                    buffer.Write(traces[i], 0, traces[i].Length);
                }
                buffer.WriteByte((byte)']');
                buffer.WriteByte((byte)'}');
                return buffer.ToArray();
            }
        }

        static void Post(HttpClient http, string url, string token, byte[] body)
        {
            using (var request = new HttpRequestMessage(HttpMethod.Post, url))
            {
                request.Headers.Add("X-Sightline-Token", token);
                request.Content = new ByteArrayContent(body);
                request.Content.Headers.ContentType = new global::System.Net.Http.Headers.MediaTypeHeaderValue("application/json");
                using (var response = http.Send(request)) { }
            }
        }
    }
